            if order != i64::try_from(n).map_err(|e| invalid(e.to_string()))? {
                return Err(invalid("Block noncontiguous ordinal"));
            }
            out.push(row);
            if (n + 1) % 256 == 0 {
                c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, n + 1, total)?;
