        }
        for row in rows.take(7, doc.rowid, c)? {
            let mut v = Cursor::new(row, 3, c);
            vortices.push(Block3dVortexTemplate { id: v.text()?, vortex_kind: v.text()?, position: v.xyz()?, direction: v.xyz()?, radius: v.float()?, label: v.optional_text()? });
