//! 📜️ Bitmap artifact — textual document grammar surface + laws (constitutional: dsl).
//!
//! The `*Dsl` types below are LOCAL structural twins of the schema tree's own records rather than
//! `#[dsl]` attributes on those records directly, for the reason the sibling assembly artifact
//! states in its own text facet: the schema file says WHAT the document is and must stay
//! representation-free, while this file says how it is SPELLED. The twins carry the same primitive
//! fields, so the bridge is mechanical in both directions and there is no second authority.

//#region 📖️SemioGrammar
/// 📖️ Normative handcrafted text grammar for this facet (`dialect grammar`).
pub const COMPONENT_GRAMMAR_SEMIO: &str = include_str!("📖️.grammar.semio");
pub const COMPONENT_GRAMMAR_PATH: &str = concat!(module_path!(), "::📖️.grammar.semio");
//#endregion 📖️SemioGrammar

use crate::schema::snapshot::{BitmapColor, BitmapInput, BitmapOutputSpec, BitmapOverlappingModel, BitmapPinnedPixel, BitmapSnapshot};

//#region 🔖️Examples
/// 📄️ The two authored bitmap problems this subset ships, in their own `.wfcbitmap` DSL.
pub const BITMAP_EXAMPLE_ROOMS_TEXT: &str = include_str!("../../../📚️examples/🚪️rooms-16/🖼️assets/🚪️rooms-16/🗣️.dsl.semio");
pub const BITMAP_EXAMPLE_FLOWERS_TEXT: &str = include_str!("../../../📚️examples/🌸️flowers-24/🖼️assets/🌸️flowers-24/🗣️.dsl.semio");
//#endregion 🔖️Examples

//#region 🔖️DslMirror
#[derive(Clone, Debug, Default, PartialEq, semio_framework_dsl_record_derive::DslRecord)]
pub struct BitmapColorDsl {
    pub r: u32,
    pub g: u32,
    pub b: u32,
    pub a: u32,
}

#[derive(Clone, Debug, Default, PartialEq, semio_framework_dsl_record_derive::DslRecord)]
pub struct BitmapPinnedPixelDsl {
    pub x: u32,
    pub y: u32,
    pub color: u32,
}

pub fn color_to_dsl(color: &BitmapColor) -> BitmapColorDsl {
    BitmapColorDsl { r: color.r, g: color.g, b: color.b, a: color.a }
}

pub fn color_from_dsl(color: &BitmapColorDsl) -> BitmapColor {
    BitmapColor { r: color.r, g: color.g, b: color.b, a: color.a }
}

pub fn pin_to_dsl(pin: &BitmapPinnedPixel) -> BitmapPinnedPixelDsl {
    BitmapPinnedPixelDsl { x: pin.x, y: pin.y, color: pin.color }
}

pub fn pin_from_dsl(pin: &BitmapPinnedPixelDsl) -> BitmapPinnedPixel {
    BitmapPinnedPixel { x: pin.x, y: pin.y, color: pin.color }
}

#[derive(Clone, Debug, PartialEq, semio_framework_dsl_record_derive::DslRecord)]
#[dsl(id = "wfc.bitmap", layout = "lines")]
struct BitmapSnapshotDsl {
    schema: String,
    seed: u64,
    input_width: u32,
    input_height: u32,
    input_pixels: String,
    output_width: u32,
    output_height: u32,
    output_periodic: bool,
    pattern_size: u32,
    symmetry: u32,
    periodic_input: bool,
    ground: Option<u32>,
    #[dsl(table)]
    palette: Vec<BitmapColorDsl>,
    #[dsl(table)]
    pinned: Vec<BitmapPinnedPixelDsl>,
}

impl Default for BitmapSnapshotDsl {
    fn default() -> Self {
        let base = BitmapSnapshot::default();
        bitmap_document_to_dsl(&base)
    }
}
//#endregion 🔖️DslMirror

//#region 🔖️HandcraftedArtifactCodecs
/// ✉️ Handcrafted `ArtifactDsl`/`ArtifactPack` — the derive stopped emitting these traits, so every
/// artifact states its own envelope discipline.
impl store::ArtifactDsl for BitmapSnapshotDsl {
    const EXTENSION: &'static str = "wfcbitmap";
    fn envelope_id() -> &'static str {
        "wfc.bitmap"
    }
    fn parse_dsl(text: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        let body = match store::semio_format::split_text_preamble(text) {
            Ok((_, rest)) => rest,
            Err(_) => text,
        };
        if body.trim().is_empty() {
            return Ok(Self::default());
        }
        let record = semio_framework_dsl_record::parse(body, &Self::__dsl_spec(), &semio_framework_dsl_record::ParseOptions { limits: semio_framework_diagnostic::Limits::default(), mode: semio_framework_dsl_record::SourceMode::Document })?;
        Self::__dsl_from_record(&record)
    }
    fn print_dsl(&self) -> String {
        let body = semio_framework_dsl_record::print(&self.__dsl_to_record(), &Self::__dsl_spec(), semio_framework_dsl_record::JoinMode::Document);
        let envelope = store::semio_format::SemioEnvelope::from_envelope_id(<Self as store::ArtifactDsl>::envelope_id(), store::semio_format::Component::Dsl, 1).expect("valid envelope_id");
        store::semio_format::wrap_text(&envelope, &body)
    }
}

impl store::ArtifactPack for BitmapSnapshotDsl {
    fn encode_pack_with(&self, options: &store::PackEncodeOptions) -> Result<Vec<u8>, store::PackError> {
        let inner = store::pack_rt::encode_document(&Self::__dsl_spec(), &self.__dsl_to_record(), options)?;
        let envelope = store::semio_format::SemioEnvelope::from_envelope_id(<Self as store::ArtifactDsl>::envelope_id(), store::semio_format::Component::Pack, 1).map_err(|error| store::PackError::Schema(error.to_string()))?;
        Ok(store::semio_format::wrap_binary(&envelope, &inner))
    }
    fn decode_pack_with(bytes: &[u8], options: &store::PackDecodeOptions) -> Result<Self, store::PackError> {
        if bytes.is_empty() {
            return Ok(Self::default());
        }
        let (envelope, inner) = store::semio_format::unwrap_binary(bytes).map_err(|error| store::PackError::Schema(error.to_string()))?;
        if !envelope.matches_identity(<Self as store::ArtifactDsl>::envelope_id(), store::semio_format::Component::Pack, 1) {
            return Err(store::PackError::Schema(format!("pack envelope mismatch: expected {}.pack v1, got {}", <Self as store::ArtifactDsl>::envelope_id(), envelope.binary_token())));
        }
        let (record, _report) = store::pack_rt::decode_document(&inner, &Self::__dsl_spec(), options)?;
        Self::__dsl_from_record(&record).map_err(store::text_error_to_pack_error)
    }
    fn record_spec() -> Option<semio_framework_dsl_record::RecordSpec> {
        Some(Self::__dsl_spec())
    }
}

fn bitmap_document_to_dsl(document: &BitmapSnapshot) -> BitmapSnapshotDsl {
    BitmapSnapshotDsl {
        schema: document.schema.clone(),
        seed: document.seed,
        input_width: document.input.width,
        input_height: document.input.height,
        input_pixels: document.input.pixels.clone(),
        output_width: document.output.width,
        output_height: document.output.height,
        output_periodic: document.output.periodic,
        pattern_size: document.model.pattern_size,
        symmetry: document.model.symmetry,
        periodic_input: document.model.periodic_input,
        ground: document.model.ground,
        palette: document.input.palette.iter().map(color_to_dsl).collect(),
        pinned: document.pinned.iter().map(pin_to_dsl).collect(),
    }
}

fn bitmap_document_from_dsl(parsed: BitmapSnapshotDsl) -> BitmapSnapshot {
    BitmapSnapshot {
        schema: parsed.schema,
        seed: parsed.seed,
        input: BitmapInput { width: parsed.input_width, height: parsed.input_height, palette: parsed.palette.iter().map(color_from_dsl).collect(), pixels: parsed.input_pixels },
        output: BitmapOutputSpec { width: parsed.output_width, height: parsed.output_height, periodic: parsed.output_periodic },
        model: BitmapOverlappingModel { pattern_size: parsed.pattern_size, symmetry: parsed.symmetry, periodic_input: parsed.periodic_input, ground: parsed.ground },
        pinned: parsed.pinned.iter().map(pin_from_dsl).collect(),
    }
}

/// 📍️ Positions a native refusal at the document origin while keeping its refusal kind.
fn positioned(error:semio_framework_value::ValueError)->semio_framework_diagnostic::TextError{semio_framework_diagnostic::TextError::from_value_error(error,semio_framework_diagnostic::TextSpan::at(1,1))}

/// 🛬️ Moves the authored bitmap grammar into persisted fields under one native ownership control.
pub(crate) fn decode_sqlite_snapshot_native(payload:&store::io_schema::IoPayload,control:&mut store::sqlite_snapshot::SqliteSnapshotControl<'_>)->Result<BitmapSnapshot,semio_framework_value::ValueError>{
    let maximum_rows=control.limits().max_rows;
    store::decode_sqlite_snapshot_record_native(payload,<BitmapSnapshot as store::ArtifactDsl>::envelope_id(),BitmapSnapshotDsl::__dsl_spec_producer(),|record,native|{
        let parsed=BitmapSnapshotDsl::__dsl_from_record_controlled(record,native).map_err(positioned)?;
        let entities=parsed.palette.len().checked_add(parsed.pinned.len()).ok_or_else(||semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue,("bitmap native entity count overflow").to_string(),semio_framework_diagnostic::TextSpan::at(1,1)))?;
        if entities.checked_add(4).is_none_or(|rows|rows>maximum_rows){return Err(semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue,("bitmap native entity count exceeds caller limit").to_string(),semio_framework_diagnostic::TextSpan::at(1,1)));}
        native.scoped_stage(|native|{
            native.begin_stage(entities).map_err(positioned)?;
            let mut palette=native.allocate_vec::<BitmapColor>(parsed.palette.len()).map_err(positioned)?;
            let mut pinned=native.allocate_vec::<BitmapPinnedPixel>(parsed.pinned.len()).map_err(positioned)?;
            for color in parsed.palette{palette.push(BitmapColor{r:color.r,g:color.g,b:color.b,a:color.a});native.step().map_err(positioned)?;}
            for pin in parsed.pinned{pinned.push(BitmapPinnedPixel{x:pin.x,y:pin.y,color:pin.color});native.step().map_err(positioned)?;}
            native.checkpoint().map_err(positioned)?;
            Ok(BitmapSnapshot{schema:parsed.schema,seed:parsed.seed,input:BitmapInput{width:parsed.input_width,height:parsed.input_height,palette,pixels:parsed.input_pixels},output:BitmapOutputSpec{width:parsed.output_width,height:parsed.output_height,periodic:parsed.output_periodic},model:BitmapOverlappingModel{pattern_size:parsed.pattern_size,symmetry:parsed.symmetry,periodic_input:parsed.periodic_input,ground:parsed.ground},pinned})
        })
    },control)
}

/// 🛫️ Admits every owned bitmap native field before its canonical record and physical output.
pub(crate) fn encode_sqlite_snapshot_native(document:&BitmapSnapshot,encoding:store::sqlite_snapshot::SnapshotEncoding,control:&mut store::sqlite_snapshot::SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload,semio_framework_value::ValueError>{
    let rows=4usize.checked_add(document.input.palette.len()).and_then(|n|n.checked_add(document.pinned.len())).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"bitmap native entity count overflow"))?;
