            record.insert(2, control.scoped_stage(|control| { control.begin_stage(0)?; <ProcedureTextChild as semio_framework_dsl_record::DslField>::to_value_controlled(&snapshot.text, control) })?)?; control.step()?;
            let path = match snapshot.flow.local_owner::<crate::ProcedureFlowWorkingData>() { Some(scene) => semio_framework_value::ToValue::to_value_controlled(&scene.path, control), None => semio_framework_value::ToValue::to_value_controlled(&crate::Path::new(), control) }.map_err(|error| error.to_string())?;
            record.insert(3, semio_framework_dsl_record::FieldValue::Value(path))?; control.step()?;
            let seed = match snapshot.text.local_owner::<crate::ProcedureTextWorkingData>() { Some(scene) => semio_framework_value::ToValue::to_value_controlled(&scene.seed, control), None => semio_framework_value::ToValue::to_value_controlled(&std::collections::BTreeMap::<String, crate::Value>::new(), control) }.map_err(|error| error.to_string())?;
