    }

    fn into_snapshot(self) -> Result<ProcedureSnapshot, String> {
        let (mut flow, mut text) = (self.flow, self.text);
        let seed = neural_engine::ColdOwner::new(<std::collections::BTreeMap<String, crate::Value> as semio_framework_value::FromValue>::from_value(self.seed).map_err(|error| error.to_string())?);
